mapper.select:
SELECT , ,
       h.id AS list_entry_id, h.last_watched_at, h.progress_seconds
FROM watch_history h
JOIN 
WHERE h.user_id = #{userId} AND v.deleted_at IS NULL AND v.status = 1



            AND (h.last_watched_at, h.id) < (#{query.cursorTime}, #{query.cursorId})


            AND (h.last_watched_at, h.id) < (
                SELECT anchor.last_watched_at, anchor.id FROM watch_history anchor
                WHERE anchor.id = #{query.cursorId} AND anchor.user_id = #{userId}
            )




AND h.last_watched_at >= #{query.startTime}
AND h.last_watched_at < #{query.endTime}
